--
-- Table structure for table `anggota_penempatan`
--

DROP TABLE IF EXISTS `anggota_penempatan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `anggota_penempatan` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `anggota_id` bigint unsigned NOT NULL,
  `bahagian_id` bigint unsigned DEFAULT NULL,
  `unit_id` bigint unsigned DEFAULT NULL,
  `tarikh_mula` date NOT NULL,
  `tarikh_tamat` date DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_anggota_mula` (`anggota_id`,`tarikh_mula`),
  KEY `idx_penempatan_bahagian` (`bahagian_id`,`tarikh_mula`,`tarikh_tamat`),
  KEY `idx_penempatan_unit` (`unit_id`,`tarikh_mula`,`tarikh_tamat`),
  CONSTRAINT `anggota_penempatan_anggota_id_foreign` FOREIGN KEY (`anggota_id`) REFERENCES `anggota` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `anggota_penempatan_bahagian_id_foreign` FOREIGN KEY (`bahagian_id`) REFERENCES `bahagian` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `anggota_penempatan_unit_id_foreign` FOREIGN KEY (`unit_id`) REFERENCES `unit` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `chk_penempatan_dates` CHECK (((`tarikh_tamat` is null) or (`tarikh_tamat` >= `tarikh_mula`))),
  CONSTRAINT `chk_penempatan_exactly_one` CHECK ((((`bahagian_id` is not null) and (`unit_id` is null)) or ((`bahagian_id` is null) and (`unit_id` is not null))))
) ENGINE=InnoDB AUTO_INCREMENT=399 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

