--
-- Table structure for table `rekod_kehadiran`
--

DROP TABLE IF EXISTS `rekod_kehadiran`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rekod_kehadiran` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `anggota_id` bigint unsigned NOT NULL,
  `penempatan_id` bigint unsigned NOT NULL,
  `status_id` smallint unsigned NOT NULL,
  `tarikh` date NOT NULL,
  `sepanjang_hari` tinyint(1) NOT NULL DEFAULT '1',
  `masa_mula` time DEFAULT NULL,
  `masa_tamat` time DEFAULT NULL,
  `lokasi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `catatan` text COLLATE utf8mb4_unicode_ci,
  `created_by` bigint unsigned DEFAULT NULL,
  `updated_by` bigint unsigned DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_harian` (`anggota_id`,`tarikh`),
  KEY `idx_calendar` (`tarikh`,`status_id`),
  KEY `idx_kehadiran_penempatan` (`penempatan_id`,`tarikh`),
  KEY `rekod_kehadiran_penempatan_id_anggota_id_foreign` (`penempatan_id`,`anggota_id`),
  KEY `rekod_kehadiran_status_id_foreign` (`status_id`),
  KEY `rekod_kehadiran_created_by_foreign` (`created_by`),
  KEY `rekod_kehadiran_updated_by_foreign` (`updated_by`),
  CONSTRAINT `rekod_kehadiran_anggota_id_foreign` FOREIGN KEY (`anggota_id`) REFERENCES `anggota` (`id`),
  CONSTRAINT `rekod_kehadiran_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `rekod_kehadiran_penempatan_id_foreign` FOREIGN KEY (`penempatan_id`) REFERENCES `anggota_penempatan` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `rekod_kehadiran_status_id_foreign` FOREIGN KEY (`status_id`) REFERENCES `status_kehadiran` (`id`),
  CONSTRAINT `rekod_kehadiran_updated_by_foreign` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`),
  CONSTRAINT `chk_kehadiran_time` CHECK (((`masa_mula` is null) or (`masa_tamat` is null) or (`masa_tamat` > `masa_mula`)))
) ENGINE=InnoDB AUTO_INCREMENT=338 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

